syntax:
// Registration signature
int std::atexit(void (*func)(void));

// Sequencing rules:
// Rule 1: obj init -> atexit(f) => f() -> ~obj()
// Rule 2: atexit(f) -> obj init => ~obj() -> f()
// Rule 3: atexit(f1) -> atexit(f2) => f2() -> f1()

// Undefined Behavior scenarios:
// - Using std lib after static destruction starts
// - Accessing destroyed static object
// - Signal-unsafe operations in atexit handlers during destruction

code_example:
#include <cstdlib>
#include <iostream>
#include <string>

// Static object with constructor/destructor
class Logger {
public:
    Logger() { std::cout << "Logger constructed\n"; }
    ~Logger() { std::cout << "Logger destroyed\n"; }
    void log(const std::string& msg) { std::cout << "LOG: " << msg << "\n"; }
};

static Logger global_logger;

// Exit handlers
void cleanup1() {
    std::cout << "cleanup1() called\n";
    // SAFE: global_logger initialized before atexit registration below
    global_logger.log("cleanup1 using logger");
}

void cleanup2() {
    std::cout << "cleanup2() called\n";
}

int main() {
    std::cout << "main() started\n";

    // Register exit handlers (LIFO order)
    std::atexit(cleanup1);  // Registered first, called SECOND
    std::atexit(cleanup2);  // Registered second, called FIRST

    std::cout << "main() ending\n";
    return 0;
}

// Output:
// Logger constructed
// main() started
// main() ending
// cleanup2() called          <- Second registered, called first
// cleanup1() called          <- First registered, called second
// LOG: cleanup1 using logger <- Logger still alive (initialized before atexit)
// Logger destroyed           <- Destroyed after atexit handlers
